<script lang="ts">import { enhance } from '$app/forms';import { MessageSquareText, ShieldAlert } from '@lucide/svelte';import ActionToast from '$lib/components/ActionToast.svelte';let{data,form}=$props();const date=(v:string|Date)=>new Date(v).toLocaleString('en-PK',{dateStyle:'medium',timeStyle:'short'});</script><svelte:head><title>Manage feedback | ZAC Admin</title></svelte:head><div class="page-title"><div><span class="eyebrow">Student voice</span><h1>Feedback</h1><p>Questions, suggestions, and corrections shared through ZAC.</p></div></div>{#if form?.error}<ActionToast type="error" message={form.error}/>{/if}{#if form?.success}<ActionToast title="Feedback updated" message="The feedback status has been saved."/>{/if}{#if !data.databaseConfigured||data.databaseError}<div class="admin-alert"><ShieldAlert size={17}/><span><b>{data.databaseConfigured?'Could not load feedback':'Database not configured'}</b><small>Check DATABASE_URL and the database connection.</small></span></div>{:else if data.rows.length}<div class="feedback-list">{#each data.rows as note}<article><div class="feedback-top"><span><MessageSquareText size={14}/>{note.category}</span><time>{date(note.createdAt)}</time><span class="feedback-status {note.status}">{note.status}</span></div><p>{note.message}</p>{#if note.email}<a class="feedback-email" href="mailto:{note.email}">{note.email}</a>{/if}<form method="POST" action="?/status" use:enhance><input type="hidden" name="id" value={note.id}/><label for="status-{note.id}">Update status</label><select id="status-{note.id}" name="status" value={note.status}><option value="new">New</option><option value="reviewed">Reviewed</option><option value="resolved">Resolved</option></select><button class="button button-outline">Save</button></form><div class="reply-editor"><p class="consent-state">{note.publicRequested ? 'Submitter opted into public sharing.' : 'Private: the submitter did not opt into public sharing.'}</p><form method="POST" action="?/reply" use:enhance><input type="hidden" name="id" value={note.id}/><label for="reply-{note.id}">Reply from ZAC team</label><textarea id="reply-{note.id}" name="reply" rows="3" maxlength="2000" placeholder="Reply or leave blank to publish only the feedback. Review text for personal details before publishing.">{note.adminReply ?? ''}</textarea><label class="publish-toggle"><input type="checkbox" name="isPublic" value="true" checked={note.isPublic} disabled={!note.publicRequested}/> Show feedback and reply publicly</label><button class="button button-outline" type="submit">Save reply and visibility</button></form></div></article>{/each}</div>{:else}<div class="empty"><MessageSquareText size={22}/><b>No feedback yet</b><span>Feedback submitted through the public form will appear here.</span></div>{/if}
