:1px solid #e7edf1;border-radius:8px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;color:#668a83}.empty b{color:#405e71;font-size:12px}.empty span{color:#83919d;font-size:10px}.admin-alert{display:flex;align-items:center;gap:11px;background:#fff8e9;border:1px solid #f0e2bd;border-radius:8px;padding:13px;color:#96783d}.admin-alert b,.admin-alert small{display:block}.admin-alert b{font-size:11px}.admin-alert small{font-size:9px;margin-top:4px}</style>
